(() => {
const root=document.documentElement.dataset.root||'../',host=document.querySelector('[data-app-groups]'),empty=document.querySelector('[data-app-empty]'),search=document.querySelector('[data-app-search]'),categoryFilter=document.querySelector('[data-app-category]'),count=document.querySelector('[data-app-count]'),selectedCount=document.querySelector('[data-selected-count]'),selectedBadge=document.querySelector('[data-selected-badge]'),selectedList=document.querySelector('[data-selected-list]'),preview=document.querySelector('[data-script-preview]'),downloadButton=document.querySelector('[data-download-script]'),copyButton=document.querySelector('[data-copy-script]'),clearButton=document.querySelector('[data-clear-selection]'),selectVisibleButton=document.querySelector('[data-select-visible]'),status=document.querySelector('[data-script-status]'),targetButtons=Array.from(document.querySelectorAll('[data-target-os]'));
const safePackageId=/^[A-Za-z0-9][A-Za-z0-9._+-]*$/,categoryNames={browser:'Web browsers',communication:'Messaging & communication',diagnostics:'Diagnostics & hardware',developer:'Developer tools','file-utility':'File utilities',media:'Media',network:'Network & transfers','boot-media':'Boot & recovery',productivity:'Productivity','remote-support':'Remote support',screenshot:'Screenshots & capture','system-utility':'System utilities',search:'Search tools'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),initials=n=>String(n||'APP').replace(/[^A-Za-z0-9 ]/g,' ').trim().split(/\s+/).slice(0,2).map(p=>p[0]||'').join('').toUpperCase();
let apps=[],selected=new Set(),targetOS='Windows 11';
function categoryName(v){const k=String(v||'other').toLowerCase();return categoryNames[k]||k.replaceAll('-',' ').replace(/\b\w/g,c=>c.toUpperCase());}
function canInstall(a){return typeof a.winget_id==='string'&&safePackageId.test(a.winget_id)&&a.verification_status!=='withdrawn';}
function filteredApps(){const q=String(search.value||'').toLowerCase().trim(),cat=categoryFilter.value;return apps.filter(a=>[a.name,a.description,a.publisher,a.category,a.winget_id].join(' ').toLowerCase().includes(q)&&(cat==='all'||a.category===cat)&&canInstall(a));}
function appMarkup(a){return '<label class="software-app"><input type="checkbox" data-app-select value="'+esc(a.id)+'"'+(selected.has(a.id)?' checked':'')+'><span class="software-check" aria-hidden="true"></span><span class="software-app-icon" aria-hidden="true">'+esc(initials(a.name))+'</span><span class="software-app-copy"><strong>'+esc(a.name)+'</strong><p>'+esc(a.description)+'</p><small>'+esc(a.publisher)+' · '+esc(a.winget_id)+'</small>'+(a.verification_status==='verified'?'<span class="status-pill status-pill--verified">Tinjauan selesai</span>':'<span class="software-app-status">Menunggu tinjauan</span>')+'</span></label>';}
function renderApps(){const shown=filteredApps(),groups=new Map();shown.forEach(a=>{const k=a.category||'other';if(!groups.has(k))groups.set(k,[]);groups.get(k).push(a);});host.innerHTML=Array.from(groups.entries()).sort((a,b)=>categoryName(a[0]).localeCompare(categoryName(b[0]))).map(([k,list])=>'<section class="software-app-group"><div class="software-app-group-head"><h2>'+esc(categoryName(k))+'</h2><span>'+list.length+' aplikasi</span></div><div class="software-app-list">'+list.map(appMarkup).join('')+'</div></section>').join('');count.textContent=shown.length+' aplikasi tersedia';empty.hidden=shown.length>0;host.hidden=!shown.length;selectVisibleButton.textContent=shown.length&&shown.every(a=>selected.has(a.id))?'Lepas pilihan yang terlihat':'Pilih yang terlihat';updateSelectionPanel();}
function scriptText(){const chosen=apps.filter(a=>selected.has(a.id)&&canInstall(a));if(!chosen.length)return '';const lines=['# ANTO-LTG WinGet bundle','# Target OS: '+targetOS,'# Generated locally from selected package IDs. Review before running.','$ErrorActionPreference = "Stop"','$TargetOS = "'+targetOS+'"','$BuildNumber = [int](Get-CimInstance Win32_OperatingSystem).BuildNumber','if ($TargetOS -eq "Windows 11" -and $BuildNumber -lt 22000) { throw "This bundle targets Windows 11, but this device appears to be Windows 10 or earlier." }','if ($TargetOS -eq "Windows 10" -and ($BuildNumber -lt 10240 -or $BuildNumber -ge 22000)) { throw "This bundle targets Windows 10, but this device does not match that target." }','if (-not (Get-Command winget.exe -ErrorAction SilentlyContinue)) { throw "WinGet was not found. Install or update App Installer from Microsoft Store first." }','','$Packages = @('];chosen.forEach((a,i)=>lines.push("  [pscustomobject]@{ Name = '"+String(a.name).replace(/'/g,"''")+"'; Id = '"+a.winget_id+"' }"+(i<chosen.length-1?',':'')));lines.push(')','','Write-Host ("ANTO-LTG will attempt to install {0} application(s) for {1}." -f $Packages.Count, $TargetOS) -ForegroundColor Cyan','Write-Warning "Catalog package IDs and compatibility may still be pending review. Check the package list before continuing."','$Confirmation = Read-Host "Type YES to continue"','if ($Confirmation -cne "YES") { Write-Host "Cancelled."; exit 0 }','','$Failed = @()','foreach ($Package in $Packages) {','  Write-Host ("Installing {0} ({1})" -f $Package.Name, $Package.Id) -ForegroundColor Cyan','  & winget.exe install --id $Package.Id --exact --source winget --accept-source-agreements --accept-package-agreements','  if ($LASTEXITCODE -ne 0) { $Failed += $Package; Write-Warning ("Install failed (exit {0}): {1}" -f $LASTEXITCODE, $Package.Name) }','}','','if ($Failed.Count -gt 0) {','  Write-Host "Some packages did not install:" -ForegroundColor Yellow','  $Failed | ForEach-Object { Write-Host (" - {0} ({1})" -f $_.Name, $_.Id) }','  exit 1','}','Write-Host "All selected install commands completed successfully." -ForegroundColor Green');return lines.join('\r\n')+'\r\n';}
function updateSelectionPanel(){const chosen=apps.filter(a=>selected.has(a.id)&&canInstall(a));selectedCount.textContent=String(chosen.length);selectedBadge.textContent=String(chosen.length);selectedList.innerHTML=chosen.length?chosen.map(a=>'<div class="selected-app-row"><span aria-hidden="true">'+esc(initials(a.name))+'</span><span class="selected-app-copy"><strong>'+esc(a.name)+'</strong><small>'+esc(a.winget_id)+'</small></span><button class="selected-app-remove" type="button" data-remove-app="'+esc(a.id)+'" aria-label="Hapus '+esc(a.name)+' dari pilihan">×</button></div>').join(''):'<div class="selected-empty">Pilih aplikasi di katalog untuk mulai menyusun paket.</div>';preview.value=scriptText();downloadButton.disabled=!chosen.length;copyButton.disabled=!chosen.length;clearButton.disabled=!chosen.length;}
function setStatus(m){status.textContent=m;}
function downloadScript(){const text=scriptText();if(!text)return;const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='anto-ltg-install.ps1';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);setStatus('Skrip diunduh. Periksa isi file sebelum menjalankannya di Windows.');}
async function copyScript(){const text=scriptText();if(!text)return;try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else{preview.focus();preview.select();if(!document.execCommand('copy'))throw new Error('copy failed');}setStatus('Skrip berhasil disalin ke clipboard.');}catch{preview.focus();preview.select();setStatus('Clipboard tidak tersedia. Skrip sudah dipilih—salin dengan Ctrl+C.');}}
fetch(root+'api/v1/apps.json').then(r=>{if(!r.ok)throw new Error('Catalog unavailable');return r.json();}).then(data=>{apps=(Array.isArray(data.items)?data.items:[]).filter(canInstall);Array.from(new Set(apps.map(a=>a.category||'other'))).sort((a,b)=>categoryName(a).localeCompare(categoryName(b))).forEach(k=>{const o=document.createElement('option');o.value=k;o.textContent=categoryName(k);categoryFilter.append(o);});renderApps();setStatus('ID WinGet dan kompatibilitas tetap perlu ditinjau sebelum digunakan di komputer servis.');}).catch(()=>{count.textContent='Katalog tidak dapat dimuat';host.hidden=true;empty.hidden=false;setStatus('Katalog aplikasi sementara tidak tersedia. Coba muat ulang halaman.');});
host.addEventListener('change',e=>{const input=e.target.closest('[data-app-select]');if(!input)return;if(input.checked)selected.add(input.value);else selected.delete(input.value);renderApps();});
selectedList.addEventListener('click',e=>{const b=e.target.closest('[data-remove-app]');if(!b)return;selected.delete(b.dataset.removeApp);renderApps();});
search.addEventListener('input',renderApps);categoryFilter.addEventListener('change',renderApps);targetButtons.forEach(button=>button.addEventListener('click',()=>{targetOS=button.dataset.targetOs;targetButtons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));updateSelectionPanel();setStatus('Target skrip diatur ke '+targetOS+'. Periksa target Windows pada komputer sebelum menjalankan.');}));
selectVisibleButton.addEventListener('click',()=>{const shown=filteredApps();if(shown.length&&shown.every(a=>selected.has(a.id)))shown.forEach(a=>selected.delete(a.id));else shown.forEach(a=>selected.add(a.id));renderApps();});
clearButton.addEventListener('click',()=>{selected.clear();renderApps();setStatus('Pilihan dikosongkan.');});downloadButton.addEventListener('click',downloadScript);copyButton.addEventListener('click',copyScript);
})();